mod review_timer_regression {
    use super::Cache;
    use crate::{common::time::Clock, Expiry};
    use std::time::{Duration, Instant};

    struct ClearOnRead;
    impl Expiry<u32, u32> for ClearOnRead {
        fn expire_after_create(&self, _: &u32, _: &u32, _: Instant) -> Option<Duration> {
            Some(Duration::from_secs(1))
        }
        fn expire_after_read(&self, _: &u32, _: &u32, _: Instant, _: Option<Duration>, _: Instant) -> Option<Duration> {
            None
        }
    }

    #[test]
    fn cleared_expiry_releases_timer_handle() {
        let (clock, mock) = Clock::mock();
        let cache = Cache::builder().clock(clock).expire_after(ClearOnRead).build();
        cache.insert(0, 1);
        cache.run_pending_tasks();
        let mut calls = 0;
        let entry = cache.entry(0).or_insert_with_if(|| 2, |_| {
            calls += 1;
            calls == 1
        });
        assert_eq!(entry.into_value(), 1);
        assert_eq!(calls, 2);
        mock.increment(Duration::from_secs(2));
        cache.run_pending_tasks();
        let hash = cache.base.hash(&0);
        let entry = cache.base.inner.cache.get(hash, |key| **key == 0).unwrap();
        assert!(entry.entry_info().expiration_time().is_none());
        assert!(entry.timer_node().is_none(), "timer node was freed but its handle remains");
    }
}
