#[test]
fn sync_weight_tracks_latest_value_when_write_logs_arrive_out_of_order() {
    use std::sync::{Arc, Barrier};
    struct PauseSecond {
        entered: Arc<Barrier>,
        release: Arc<Barrier>,
    }
    impl moka::Expiry<u32, u32> for PauseSecond {
        fn expire_after_update(&self, _: &u32, value: &u32, _: std::time::Instant, current: Option<std::time::Duration>) -> Option<std::time::Duration> {
            if *value == 2 {
                self.entered.wait();
                self.release.wait();
            }
            current
        }
    }
    let entered = Arc::new(Barrier::new(2));
    let release = Arc::new(Barrier::new(2));
    let cache = sync::Cache::builder()
        .weigher(|_: &u32, value: &u32| *value)
        .expire_after(PauseSecond { entered: entered.clone(), release: release.clone() })
        .build();
    cache.insert(0, 1);
    cache.run_pending_tasks();
    let worker_cache = cache.clone();
    let worker = std::thread::spawn(move || worker_cache.insert(0, 2));
    entered.wait();
    cache.insert(0, 3);
    cache.run_pending_tasks();
    release.wait();
    worker.join().unwrap();
    cache.run_pending_tasks();
    assert_eq!(cache.get(&0), Some(3));
    assert_eq!(cache.entry_count(), 1);
    assert_eq!(cache.weighted_size(), 3);
}
